import hashlib
import hmac
import os
import time
import threading
from collections import OrderedDict
from typing import Optional, Tuple

# Secure session store with LRU eviction
class SessionStore:
    def __init__(self, max_sessions: int = 10000, secret: bytes = None):
        self._lock = threading.Lock()
        self._sessions: OrderedDict = OrderedDict()
        self._max_sessions = max_sessions
        self._secret = secret or os.urandom(32)
        self._refresh_lock = threading.Lock()
        self._pending_refreshes: dict = {}

    def _generate_token(self) -> str:
        return os.urandom(32).hex()

    def _compute_mac(self, token: str, user_id: str, expires: float) -> str:
        msg = f"{token}:{user_id}:{expires}".encode()
        return hmac.new(self._secret, msg, hashlib.sha256).hexdigest()

    def create_session(self, user_id: str, ttl: int = 3600) -> dict:
        token = self._generate_token()
        expires = time.time() + ttl
        mac = self._compute_mac(token, user_id, expires)
        session = {
            "token": token,
            "user_id": user_id,
            "expires": expires,
            "mac": mac,
            "created": time.time()
        }
        with self._lock:
            self._sessions[token] = session
            if len(self._sessions) > self._max_sessions:
                self._sessions.popitem(last=False)
        return session

    def validate_session(self, token: str) -> Optional[dict]:
        with self._lock:
            session = self._sessions.get(token)
            if session is None:
                return None
            # Move to end for LRU
            self._sessions.move_to_end(token)

            # Verify MAC inside lock for atomicity
            expected_mac = self._compute_mac(
                session["token"], session["user_id"], session["expires"]
            )
            if not hmac.compare_digest(expected_mac, session["mac"]):
                return None

            if time.time() > session["expires"]:
                self._sessions.pop(token, None)
                return None

            return session.copy()

    def refresh_session(self, old_token: str, ttl: int = 3600) -> Optional[dict]:
        """Atomically refresh a session with a new token."""
        with self._lock:
            # Check if refresh is already pending for this token
            if old_token in self._pending_refreshes:
                # Return the already-refreshed session
                return self._pending_refreshes[old_token].copy()

            # Validate the old session inline
            old_session = self._sessions.get(old_token)
            if old_session is None:
                return None

            # Verify MAC
            expected_mac = self._compute_mac(
                old_session["token"], old_session["user_id"], old_session["expires"]
            )
            if not hmac.compare_digest(expected_mac, old_session["mac"]):
                return None

            if time.time() > old_session["expires"]:
                self._sessions.pop(old_token, None)
                return None

            # Generate new session
            new_token = self._generate_token()
            new_expires = time.time() + ttl
            new_mac = self._compute_mac(new_token, old_session["user_id"], new_expires)
            new_session = {
                "token": new_token,
                "user_id": old_session["user_id"],
                "expires": new_expires,
                "mac": new_mac,
                "created": time.time()
            }

            # Remove old, add new atomically
            self._sessions.pop(old_token, None)
            self._sessions[new_token] = new_session
            self._pending_refreshes[old_token] = new_session

        # Cleanup pending refreshes after a delay
        def _cleanup():
            time.sleep(2)
            with self._lock:
                self._pending_refreshes.pop(old_token, None)
        threading.Thread(target=_cleanup, daemon=True).start()

        return new_session.copy()

    def invalidate_session(self, token: str) -> bool:
        with self._lock:
            return self._sessions.pop(token, None) is not None


class AuthMiddleware:
    # Maximum number of distinct rate-limit buckets kept in memory.
    _MAX_RATE_LIMIT_ENTRIES = 100000
    _RATE_WINDOW = 60

    def __init__(self, store: SessionStore):
        self.store = store
        self._rate_limits: dict = {}
        self._rate_lock = threading.Lock()

    def _prune_rate_limits(self, now: float) -> None:
        """Remove expired rate-limit windows. Caller must hold _rate_lock."""
        expired = [
            p for p, (_, window_start) in self._rate_limits.items()
            if now - window_start >= self._RATE_WINDOW
        ]
        for p in expired:
            self._rate_limits.pop(p, None)

        # Hard cap as a safety net against pathological / high-cardinality abuse.
        if len(self._rate_limits) > self._MAX_RATE_LIMIT_ENTRIES:
            # Drop the oldest windows first.
            for p, _ in sorted(
                self._rate_limits.items(), key=lambda kv: kv[1][1]
            )[: len(self._rate_limits) - self._MAX_RATE_LIMIT_ENTRIES]:
                self._rate_limits.pop(p, None)

    def authenticate(self, token: str) -> Tuple[bool, Optional[str]]:
        """Returns (is_authenticated, user_id)"""
        if not token or not isinstance(token, str):
            return (False, None)

        if len(token) != 64:  # 32 bytes hex = 64 chars
            return (False, None)

        # Rate limiting by token prefix
        prefix = token[:8]
        with self._rate_lock:
            now = time.time()
            # Bound memory usage by pruning expired / excess buckets.
            self._prune_rate_limits(now)
            if prefix in self._rate_limits:
                count, window_start = self._rate_limits[prefix]
                if now - window_start < self._RATE_WINDOW:
                    if count > 100:
                        return (False, None)
                    self._rate_limits[prefix] = (count + 1, window_start)
                else:
                    self._rate_limits[prefix] = (1, now)
            else:
                self._rate_limits[prefix] = (1, now)

        session = self.store.validate_session(token)
        if session is None:
            return (False, None)

        return (True, session["user_id"])

    def refresh(self, token: str) -> Tuple[bool, Optional[dict]]:
        """Refresh a session token. Returns (success, new_session)"""
        if not token or len(token) != 64:
            return (False, None)

        new_session = self.store.refresh_session(token)
        if new_session is None:
            return (False, None)

        return (True, new_session)


def handle_request(middleware: AuthMiddleware, headers: dict) -> dict:
    """Simulate HTTP request handling."""
    auth_header = headers.get("Authorization", "")
    if not auth_header.startswith("Bearer "):
        return {"status": 401, "body": "Missing authorization"}

    token = auth_header[7:]

    # Check if this is a refresh request
    if headers.get("X-Refresh-Token") == "true":
        success, new_session = middleware.refresh(token)
        if success:
            return {"status": 200, "body": {"new_token": new_session["token"]}}
        return {"status": 401, "body": "Refresh failed"}

    # Normal authentication
    is_auth, user_id = middleware.authenticate(token)
    if not is_auth:
        return {"status": 401, "body": "Unauthorized"}

    return {"status": 200, "body": f"Hello, {user_id}"}
